type Described = {
  label: UI.ReactNode;
  payload: ChartTooltipItem[];
  announce: string;
};
interface CanvasProps<S extends ChartSpec> extends Omit<UI.ComponentProps<"div">, "children" | "onChange" | "onSelect"> {
  slot?: string;
  recipe: Recipe<S>;
  spec: S;
  kindLabel: string;
