  })
  const many = spec.series.length
  const extra = (spec.stacked ? ' Stacked.' : spec.horizontal ? ' Horizontal bars.' : '') + (spec.total ? ` Thinned from ${formatNumber(spec.total)} rows to keep the drawing readable.` : '')
  const marked = spec.bands.length ? ` Marked: ${spec.bands.map((b) => `${b.text ? `${b.text}, ` : ''}${spec.cats[b.i0]}${b.i1 !== b.i0 ? ` to ${spec.cats[b.i1]}` : ''}`).join('; ')}.` : ''
  return `${named}${o.kind} with ${many} series (${list(spec.series.map((s) => s.name))}) and ${unit}.${extra} ${parts.join('. ')}.${marked}`.replace(/\.\./g, '.')
}

export interface TableModel {
  head: string[]
  rows: string[][]
  clipped?: { shown: number; total: number }
}

export const TABLE_ROW_CAP = 240

export function tableXY(spec: XYSpec, o: { format?: (v: number) => string; xHead?: string; xFormat?: (v: number) => string } = {}): TableModel {
  const fmt = o.format ?? formatNumber
  const scatter = spec.series.some((s) => s.kind === 'scatter')
  if (scatter) {
    const rows: string[][] = []
    spec.series.forEach((s) => {
      s.values.forEach((v, j) => {
        const x = s.xs?.[j]
        if (isNum(v) && isNum(x)) rows.push([s.name, (o.xFormat ?? fmt)(x), fmt(v)])
      })
    })
    const total = rows.length
    return { head: ['Series', o.xHead ?? 'x', 'y'], rows: rows.slice(0, TABLE_ROW_CAP), clipped: total > TABLE_ROW_CAP ? { shown: TABLE_ROW_CAP, total } : undefined }
  }
  const total = spec.cats.length
  const rows = spec.cats.slice(0, TABLE_ROW_CAP).map((c, i) => [c, ...spec.series.map((s) => (isNum(s.values[i]) ? fmt(s.values[i] as number) : ''))])
  return { head: [o.xHead ?? '', ...spec.series.map((s) => s.name)], rows, clipped: total > TABLE_ROW_CAP ? { shown: TABLE_ROW_CAP, total } : undefined }
}

export function announceRow(label: string, entries: ReadonlyArray<{ name: string; value: string }>): string {
  return `${label}: ${entries.map((e) => `${e.name} ${e.value}`).join(', ')}`
}

export { round }

import { isNum } from '@/lib/ink/charts/chart-scale'

const DAY = 86_400_000
export const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'] as const
export const MONTHS_LONG = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'] as const
export const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'] as const

export function dayMs(d: unknown): number {
  if (d instanceof Date) return Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate())
  if (typeof d === 'string') {
    const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(d)
    if (m) return Date.UTC(+m[1], +m[2] - 1, +m[3])
  }
  return Number.NaN
}

export function isoDay(ms: number): string {
  const d = new Date(ms)
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, '0')}-${String(d.getUTCDate()).padStart(2, '0')}`
}

export function formatDay(ms: number, year = false): string {
  const d = new Date(ms)
  return `${WEEKDAYS[d.getUTCDay()]}, ${MONTHS[d.getUTCMonth()]} ${d.getUTCDate()}${year ? `, ${d.getUTCFullYear()}` : ''}`
}

export function levelOf(v: number | null, max: number, levels: number, thresholds?: readonly number[]): number {
  if (!isNum(v) || v <= 0) return 0
  if (thresholds?.length) {
    let lv = 0
    for (const t of thresholds) if (v >= t) lv++
    return Math.min(levels - 1, Math.max(1, lv))
  }
  return Math.min(levels - 1, Math.max(1, Math.ceil((v / (max || 1)) * (levels - 1))))
}

export interface HeatCells {
  cols: number
  rows: number
  levels: number[]
  values: Array<number | null>
  days: number[]
  colLabels: Array<{ i: number; text: string }>
  rowLabels: Array<{ i: number; text: string }>
  max: number
}

export interface CalendarInput {
  date: unknown
  value: unknown
}

export interface CalendarOpts {
  weeks?: number
  end?: unknown
  weekStart?: 0 | 1
  levels: number
  thresholds?: readonly number[]
  weekdayLabels?: boolean
  monthLabels?: boolean
}

export function buildCalendar(rows: readonly CalendarInput[], o: CalendarOpts): HeatCells {
  const byDay = new Map<number, number>()
  let last = Number.NEGATIVE_INFINITY
  let first = Number.POSITIVE_INFINITY
  for (const r of rows) {
    const ms = dayMs(r.date)
    const v = typeof r.value === 'number' ? r.value : Number(r.value)
    if (!Number.isFinite(ms) || !Number.isFinite(v)) continue
    byDay.set(ms, (byDay.get(ms) ?? 0) + v)
    last = Math.max(last, ms)
    first = Math.min(first, ms)
  }
  const ws = o.weekStart ?? 0
  const endMs = Number.isFinite(dayMs(o.end)) ? dayMs(o.end) : Number.isFinite(last) ? last : dayMs('2026-01-01')
  const startFromData = Number.isFinite(first) ? first : endMs
  const weekOf = (ms: number) => Math.floor((ms - dayMs('1970-01-04') - ws * DAY) / (7 * DAY))
  const spanWeeks = weekOf(endMs) - weekOf(startFromData) + 1
  const weeks = Math.max(1, Math.min(o.weeks ?? Math.min(53, spanWeeks), 60))
  const lastWeek = weekOf(endMs)
  const week0 = lastWeek - weeks + 1
  const gridStart = dayMs('1970-01-04') + ws * DAY + week0 * 7 * DAY
  let max = 0
  for (const [ms, v] of byDay) if (ms >= gridStart && ms <= endMs) max = Math.max(max, v)
  const levels: number[] = []
  const values: Array<number | null> = []
  const days: number[] = []
  for (let r = 0; r < 7; r++) {
    for (let c = 0; c < weeks; c++) {
      const ms = gridStart + (c * 7 + r) * DAY
      if (ms > endMs) {
        levels.push(-1)
        values.push(null)
        days.push(Number.NaN)
        continue
      }
      const v = byDay.get(ms) ?? 0
      levels.push(levelOf(v, max, o.levels, o.thresholds))
      values.push(v)
      days.push(ms)
    }
  }
  const colLabels: Array<{ i: number; text: string }> = []
  if (o.monthLabels !== false) {
    let prev = -1
    let prevCol = -99
    for (let c = 0; c < weeks; c++) {
      const ms = gridStart + c * 7 * DAY
      const month = new Date(ms).getUTCMonth()
      const startsHere = c === 0 || new Date(ms - 7 * DAY).getUTCMonth() !== month
      if (startsHere && month !== prev && c > 0 && c < 3 && colLabels.length === 1 && colLabels[0].i === 0) {
        colLabels.length = 0
        prevCol = -99
      }
      if (startsHere && month !== prev && c - prevCol >= 3) {
        colLabels.push({ i: c, text: MONTHS[month] })
        prev = month
        prevCol = c
      }
    }
  }
  const rowLabels: Array<{ i: number; text: string }> = []
  if (o.weekdayLabels !== false) for (const wd of [1, 3, 5]) rowLabels.push({ i: (wd - ws + 7) % 7, text: WEEKDAYS[wd] })
  return { cols: weeks, rows: 7, levels, values, days, colLabels, rowLabels, max }
}

export interface GridInput {
  row: unknown
  col: unknown
  value: unknown
}

export function buildGrid(data: readonly GridInput[], o: { rows?: readonly string[]; cols?: readonly string[]; levels: number; thresholds?: readonly number[] }): HeatCells {
  const rowNames = (o.rows ? [...o.rows] : [...new Set(data.map((d) => String(d.row)))]).slice(0, 200)
  const colNames = (o.cols ? [...o.cols] : [...new Set(data.map((d) => String(d.col)))]).slice(0, 200)
  const cell = new Map<string, number>()
  let max = 0
  for (const d of data) {
    const v = typeof d.value === 'number' ? d.value : Number(d.value)
    if (!Number.isFinite(v)) continue
    const key = `${String(d.row)}\u0000${String(d.col)}`
    cell.set(key, (cell.get(key) ?? 0) + v)
  }
  for (const v of cell.values()) max = Math.max(max, v)
  const levels: number[] = []
  const values: Array<number | null> = []
  rowNames.forEach((r) =>
    colNames.forEach((c) => {
      const v = cell.get(`${r}\u0000${c}`)
      levels.push(v === undefined ? 0 : levelOf(v, max, o.levels, o.thresholds))
      values.push(v ?? 0)
    }),
  )
  return {
    cols: colNames.length,
    rows: rowNames.length,
    levels,
    values,
    days: levels.map(() => Number.NaN),
    colLabels: colNames.map((text, i) => ({ i, text })),
    rowLabels: rowNames.map((text, i) => ({ i, text })),
    max,
  }
}

import { layoutGauge, layoutPie, layoutRadar, layoutRadial, TAU } from '@/lib/ink/charts/chart-polar'
import { layoutHeat, layoutSpark, layoutTally } from '@/lib/ink/charts/chart-mini'
import { layoutXY } from '@/lib/ink/charts/chart-xy'
import type { ChartLayoutBase, ChartTargets, GaugeSpec, HeatSpec, PieSpec, RadarSpec, RadialSpec, SparkSpec, TallySpec, XYSpec } from '@/lib/ink/charts/chart-types'

export type ChartSpec = XYSpec | PieSpec | RadarSpec | RadialSpec | GaugeSpec | SparkSpec | TallySpec | HeatSpec

export function layoutChart(spec: ChartSpec, box: { w: number; h: number }, calm = false): ChartLayoutBase {
  switch (spec.type) {
    case 'xy':
      return layoutXY(spec, box, calm)
    case 'pie':
      return layoutPie(spec, box, calm)
    case 'radar':
      return layoutRadar(spec, box, calm)
    case 'radial':
      return layoutRadial(spec, box, calm)
    case 'gauge':
      return layoutGauge(spec, box, calm)
    case 'spark':
      return layoutSpark(spec, box)
    case 'tally':
      return layoutTally(spec, box, calm)
    case 'heat':
      return layoutHeat(spec, box, calm)
  }
}

const norm = (a: number): number => ((a % TAU) + TAU) % TAU

export function hitIndex(t: ChartTargets, x: number, y: number): number | null {
  if (t.n <= 0) return null
  switch (t.mode) {
    case 'x':
    case 'y': {
      const pos = t.pos ?? []
      const v = t.mode === 'x' ? x : y
      let best = -1
      let bd = Infinity
      for (let i = 0; i < pos.length; i++) {
        const d = Math.abs(pos[i] - v)
        if (d < bd) {
          bd = d
          best = i
        }
      }
      return best < 0 ? null : best
    }
    case 'point': {
      let best = -1
      let bd = 40 * 40
      for (let i = 0; i < t.n; i++) {
        const d = (t.cx[i] - x) ** 2 + (t.cy[i] - y) ** 2
        if (d < bd) {
          bd = d
          best = i
        }
      }
      return best < 0 ? null : best
    }
    case 'sector': {
      const s = t.sector
      if (!s) return null
      const r = Math.hypot(x - s.cx, y - s.cy)
      const ang = Math.atan2(x - s.cx, s.cy - y)
      for (let i = 0; i < t.n; i++) {
        if (r < s.r0[i] || r > s.r1[i]) continue
        const span = s.a1[i] - s.a0[i]
        if (norm(ang - s.a0[i]) <= span + 1e-9) return i
      }
      return null
    }
    case 'cell': {
      const c = t.cells
      if (!c) return null
      const col = Math.floor((x - c.x0) / c.cw)
      const row = Math.floor((y - c.y0) / c.ch)
      if (col < 0 || row < 0 || col >= c.cols || row >= c.rows) return null
      const k = row * c.cols + col
      return c.index[k] >= 0 ? k : null
    }
  }
}

const clampI = (v: number, n: number): number => Math.max(0, Math.min(n - 1, v))

export function stepIndex(t: ChartTargets, from: number | null, key: string): number | null {
  const n = t.n
  if (n <= 0) return null
  const cur = from == null || from < 0 || from >= n ? null : from
  if (key === 'Home') return t.mode === 'cell' ? firstCell(t) : 0
  if (key === 'End') return t.mode === 'cell' ? lastCell(t) : n - 1
  if (t.mode === 'cell' && t.cells) {
    const c = t.cells
    const d = key === 'ArrowRight' ? [1, 0] : key === 'ArrowLeft' ? [-1, 0] : key === 'ArrowDown' ? [0, 1] : key === 'ArrowUp' ? [0, -1] : key === 'PageDown' ? [7, 0] : key === 'PageUp' ? [-7, 0] : null
    if (!d) return null
    if (cur == null) return firstCell(t)
    let col = cur % c.cols
    let row = Math.floor(cur / c.cols)
    for (let guard = 0; guard < c.cols + c.rows; guard++) {
      col += d[0]
      row += d[1]
      if (col < 0 || row < 0 || col >= c.cols || row >= c.rows) return cur
      const k = row * c.cols + col
      if (c.index[k] >= 0) return k
    }
    return cur
  }
  const forward = t.mode === 'y' ? key === 'ArrowDown' : t.mode === 'sector' ? key === 'ArrowRight' || key === 'ArrowDown' : key === 'ArrowRight'
  const backward = t.mode === 'y' ? key === 'ArrowUp' : t.mode === 'sector' ? key === 'ArrowLeft' || key === 'ArrowUp' : key === 'ArrowLeft'
  if (!forward && !backward) return null
  if (cur == null) return forward ? 0 : n - 1
  if (t.mode === 'sector') return (cur + (forward ? 1 : -1) + n) % n
  return clampI(cur + (forward ? 1 : -1), n)
}

function firstCell(t: ChartTargets): number {
  const i = t.cells?.index.findIndex((k) => k >= 0) ?? 0
  return i < 0 ? 0 : i
}
function lastCell(t: ChartTargets): number {
  const idx = t.cells?.index ?? []
  for (let i = idx.length - 1; i >= 0; i--) if (idx[i] >= 0) return i
  return 0
}

import type { Pt } from '@/lib/ink/types'
import { bucketOf, clampN, isNum, monotoneCurve, textWidth, type LabelFont } from '@/lib/ink/charts/chart-scale'
import type { ChartLabel, ChartLayoutBase, ChartTargets, CursorSpec, HeatSpec, SparkSpec, TallySpec } from '@/lib/ink/charts/chart-types'

export interface SparkLayout extends ChartLayoutBase {
  pts: Array<Pt | null>
  segs: Pt[][]
  bars: Array<{ x: number; y: number; w: number; h: number }>
  baseY: number
  last: Pt | null
  minPt: Pt | null
  maxPt: Pt | null
}

export function layoutSpark(spec: SparkSpec, box: { w: number; h: number }): SparkLayout {
  const { w, h } = box
  const n = spec.values.length
  const padX = spec.variant === 'bar' ? 1.5 : 4
  const padY = 5
  const x0 = padX
  const x1 = w - padX - (spec.ends && spec.variant !== 'bar' ? 3 : 0)
  const y0 = padY
  const y1 = h - padY
  const span = spec.max - spec.min || 1
  const yOf = (v: number) => clampN(y1 - ((v - spec.min) / span) * (y1 - y0), y0 - 4, y1 + 4)
  const slot = n > 0 ? (x1 - x0) / n : 0
  const xOf = (i: number) => (spec.variant === 'bar' ? x0 + slot * (i + 0.5) : n < 2 ? (x0 + x1) / 2 : x0 + ((x1 - x0) * i) / (n - 1))
  const pts: Array<Pt | null> = spec.values.map((v, i) => (isNum(v) ? [xOf(i), yOf(v)] : null))
  const runs: Pt[][] = []
  let cur: Pt[] = []
  for (const p of pts) {
    if (p) cur.push(p)
    else if (cur.length) (runs.push(cur), (cur = []))
  }
  if (cur.length) runs.push(cur)
  const segs = runs.map((r) => (r.length > 2 ? monotoneCurve(r, 3) : r))
  const bw = clampN(slot * 0.62, 1.6, 14)
  const bars = spec.variant === 'bar' ? pts.flatMap((p) => (p ? [{ x: p[0] - bw / 2, y: p[1], w: bw, h: Math.max(1.2, y1 - p[1]) }] : [])) : []
  const real = pts.filter((p): p is Pt => !!p)
  const last = real.length ? real[real.length - 1] : null
  let minPt: Pt | null = null
  let maxPt: Pt | null = null
  real.forEach((p) => {
    if (!minPt || p[1] > minPt[1]) minPt = p
    if (!maxPt || p[1] < maxPt[1]) maxPt = p
  })
  const targets: ChartTargets = { n, mode: 'x', pos: pts.map((p, i) => (p ? p[0] : xOf(i))), cx: pts.map((p, i) => (p ? p[0] : xOf(i))), cy: pts.map((p) => (p ? p[1] : y1)), nav: 'linear' }
  const cursorAt = (i: number): CursorSpec[] => {
    const p = pts[i]
    return p ? [{ kind: 'ring', x: p[0] - 7, y: p[1] - 7, w: 14, h: 14, slot: spec.slot }] : []
  }
  return { w, h, bucket: bucketOf(w), labels: [], targets, cursorAt, pts, segs, bars, baseY: y1, last, minPt, maxPt }
}

export interface TallyRowGeom {
  index: number
  y: number
  gh: number
  x: number
  marks: number
  right: number
}
export interface TallyLayout extends ChartLayoutBase {
  rows: TallyRowGeom[]
  unit: number
  markArea: { x0: number; x1: number }
}

export const MAX_MARKS = 250
const TALLY_UNITS = [1, 2, 5, 10, 20, 25, 50, 100, 200, 250, 500, 1000, 2000, 5000, 10000, 100000]

export function layoutTally(spec: TallySpec, box: { w: number; h: number }, calm = false): TallyLayout {
  const { w, h } = box
  const bucket = bucketOf(w)
  const font: LabelFont = calm ? 'hand' : 'script'
  const tick = calm ? 13 : bucket === 'sm' ? 15 : 17
  const labels: ChartLabel[] = []
  const m = spec.rows.length
  const nameW = Math.min(w * 0.34, Math.max(0, ...spec.rows.map((r) => textWidth(r.name, tick, font))) + 4)
  const totalW = Math.max(0, ...spec.totals.map((t) => textWidth(t, tick, font))) + 6
  const x0 = nameW + 14
  const x1 = w - totalW - 10
  const rh = m ? clampN((h - 8) / m, 24, 52) : 40
  const gh = clampN(rh * 0.62, 14, 28)
  const maxCount = Math.max(1, ...spec.rows.map((r) => (Number.isFinite(r.count) ? r.count : 0)))
  const groupW = (g: number) => 1.05 * g + 6
  const fits = (unit: number) => Math.ceil(maxCount / unit / 5) * groupW(gh) - 6 <= x1 - x0
  const need = Math.ceil(maxCount / MAX_MARKS)
  const floor = TALLY_UNITS.find((u) => u >= need) ?? need
  const unit = Math.max(floor, spec.unit > 0 ? spec.unit : (TALLY_UNITS.find(fits) ?? TALLY_UNITS[TALLY_UNITS.length - 1]))
  const usedH = m * rh
  const top = Math.max(4, Math.min(12, (h - usedH) / 2))
  const rows: TallyRowGeom[] = spec.rows.map((r, i) => {
    const marks = Math.ceil((Number.isFinite(r.count) ? r.count : 0) / unit)
    const groups = Math.ceil(marks / 5)
    const y = top + i * rh + (rh - gh) / 2
    const right = x0 + Math.max(0, groups * groupW(gh) - 6 - (marks % 5 && marks % 5 !== 0 ? (5 - (marks % 5)) * 0.26 * gh : 0))
    labels.push({ id: `n-${i}`, text: r.name, x: 4, y: y + gh / 2, anchor: 'start', valign: 'middle', role: 'cat', size: tick, tone: 'ink', maxW: nameW })
    labels.push({ id: `t-${i}`, text: spec.totals[i] ?? String(r.count), x: w - 4, y: y + gh / 2, anchor: 'end', valign: 'middle', role: 'value', size: tick, tone: 'muted' })
    return { index: i, y, gh, x: x0, marks, right }
  })
  if (unit > 1 && spec.state === 'ready') {
    labels.push({ id: 'unit', text: `each mark = ${unit}`, x: w - 4, y: h - 2, anchor: 'end', valign: 'bottom', role: 'sub', size: Math.max(12, tick - 3), tone: 'muted' })
  }
  if (spec.state !== 'ready' || !m) labels.push({ id: 'state', text: spec.stateText ?? (spec.state === 'loading' ? 'Loading' : 'No data'), x: w / 2, y: h / 2, anchor: 'middle', valign: 'middle', role: 'center', size: 20, tone: 'muted' })
  const targets: ChartTargets = { n: m, mode: 'y', pos: rows.map((r) => r.y + r.gh / 2), cx: rows.map((r) => (r.right + x0) / 2), cy: rows.map((r) => r.y + r.gh / 2), nav: 'linear' }
  const cursorAt = (i: number): CursorSpec[] => {
    const r = rows[i]
    return r ? [{ kind: 'column', x: 0, y: r.y - (rh - r.gh) / 2, w, h: rh }] : []
  }
  return { w, h, bucket, labels, targets, cursorAt, rows, unit, markArea: { x0, x1 } }
}

export interface HeatCell {
  col: number
  row: number
  x: number
  y: number
  level: number
}
export interface HeatLayout extends ChartLayoutBase {
  cs: number
  cell: number
  gx: number
  gy: number
  cells: HeatCell[]
  legend: { x: number; y: number; cell: number } | null
}

export function layoutHeat(spec: HeatSpec, box: { w: number; h: number }, calm = false): HeatLayout {
  const { w, h } = box
  const bucket = bucketOf(w)
  const font: LabelFont = calm ? 'hand' : 'script'
  const tick = calm ? 12 : bucket === 'sm' ? 13 : 14.5
  const labels: ChartLabel[] = []
  const left = spec.rowLabels.length ? Math.max(...spec.rowLabels.map((r) => textWidth(r.text, tick, font))) + 10 : 4
  const top = spec.colLabels.length ? tick + 8 : 4
  const bottom = spec.legend ? tick + 16 : 4
  const availW = w - left - 4
  const availH = h - top - bottom
  const cs = Math.max(4, Math.min(availW / Math.max(1, spec.cols), availH / Math.max(1, spec.rows), 34))
  const gap = clampN(cs * 0.16, 1.4, 4.5)
  const cell = cs - gap
  const gx = left
  const gy = top + Math.max(0, (availH - cs * spec.rows) / 2)
  const cells: HeatCell[] = []
  const index: number[] = []
  spec.levels.forEach((lv, k) => {
    const col = k % spec.cols
    const row = Math.floor(k / spec.cols)
    if (lv >= 0) cells.push({ col, row, x: gx + col * cs, y: gy + row * cs, level: lv })
    index.push(lv >= 0 ? k : -1)
  })
  if (spec.state === 'ready') {
    if (spec.variant === 'grid') {
      for (const c of spec.colLabels) labels.push({ id: `c-${c.i}`, text: c.text, x: gx + c.i * cs + cs / 2, y: gy - 6, anchor: 'middle', valign: 'bottom', role: 'x', size: tick, tone: 'ink', maxW: Math.max(cs, 24) })
    } else {
      let free = Number.NEGATIVE_INFINITY
      for (const c of spec.colLabels) {
        const x = gx + c.i * cs
        if (x < free) continue
        labels.push({ id: `c-${c.i}`, text: c.text, x, y: gy - 6, anchor: 'start', valign: 'bottom', role: 'x', size: tick, tone: 'ink' })
        free = x + textWidth(c.text, tick, font) + 6
      }
    }
    let lastY = Number.NEGATIVE_INFINITY
    for (const r of spec.rowLabels) {
      const y = gy + r.i * cs + cs / 2
      if (y - lastY < tick * 0.95) continue
      labels.push({ id: `r-${r.i}`, text: r.text, x: gx - 6, y, anchor: 'end', valign: 'middle', role: 'y', size: tick, tone: 'muted' })
      lastY = y
    }
  }
